/* HEXA BATTLEGROUNDS upgrade — PART 5 OF 6. Only for databases that already ran setup part-01…; run in order. Safe to re-run. */ create or replace function host_trial_status(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; e events; begin v_ev := _auth_host(p_token); select * into e from events where id = v_ev; return jsonb_build_object( 'is_trial', e.is_trial, 'steps', jsonb_build_object( 'squads', exists (select 1 from teams where event_id = v_ev), 'joined', exists (select 1 from teams where event_id = v_ev and ready), 'boarding', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'shuttle.assigned'), 'shuttle', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'shuttle.departed'), 'roles', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'role.assignment.completed'), 'movement', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'squad.arrived'), 'mission', exists (select 1 from mission_instances mi join arenas a on a.id = mi.arena_id where a.event_id = v_ev and mi.status = 'solved' and mi.kind in ('mission', 'relay')), 'wrong_answer', exists (select 1 from submissions s join teams t on t.id = s.team_id where t.event_id = v_ev and not s.correct), 'phase2', exists (select 1 from arenas where event_id = v_ev and match_phase >= 2), 'battle', exists (select 1 from battles b join arenas a on a.id = b.arena_id where a.event_id = v_ev and b.status = 'resolved'), 'airdrop', exists (select 1 from airdrops d join arenas a on a.id = d.arena_id where a.event_id = v_ev and d.status = 'claimed'), 'zone', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'zone.collapsed'), 'recovery', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'recovery.started'), 'pause', exists (select 1 from audit_log where event_id = v_ev and action = 'resume' and ok), 'chat', exists (select 1 from chat_messages c join arenas a on a.id = c.arena_id where a.event_id = v_ev), 'finale', exists (select 1 from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev and g.type = 'final.started'), 'finale_round', exists (select 1 from mission_instances mi join arenas a on a.id = mi.arena_id where a.event_id = v_ev and mi.sync_round_id is not null and mi.status = 'solved'), 'results', exists (select 1 from arenas where event_id = v_ev and results_locked), 'winner', exists (select 1 from arenas where event_id = v_ev and winner_revealed) )); end $$; create or replace function _host_exec_p0(p_ev uuid, p_arena uuid, p_cmd text, p_args jsonb, p_reason text) returns jsonb language plpgsql as $$ declare a arenas; e events; t teams; v_delta interval; v_pin text; v_salt text; v_out jsonb := '[]'::jsonb; i int; j int; v_tokens jsonb; v_num int; v_size int; v_count int; v_names text[] := array['Ava','Ben','Cleo','Dev','Esha','Finn','Gia','Hari','Ivy','Jai','Kai','Lia','Mo','Nia','Om','Pia']; begin select * into e from events where id = p_ev; if p_arena is not null then select * into a from arenas where id = p_arena; end if; if p_cmd in ('trial_skip', 'trial_bots', 'trial_reset') and not e.is_trial then raise exception 'TRIAL_ONLY'; end if; case p_cmd when 'set_phase', 'next_phase' then if a.phase <> 'play' then raise exception 'WRONG_PHASE'; end if; i := case when p_cmd = 'next_phase' then a.match_phase + 1 else (p_args ->> 'phase')::int end; if i is null or i < 0 or i > 4 then raise exception 'BAD_PHASE'; end if; perform _set_match_phase(a.id, i); perform _tick(a.id, true); return jsonb_build_object('phase', i); when 'hide_rankings' then update arenas set overlay = overlay || jsonb_build_object('hide_rankings', coalesce((p_args ->> 'on')::boolean, true)) where id = a.id; when 'reset_pin' then select * into t from teams where id = (p_args ->> 'team_id')::uuid and event_id = p_ev for update; if t.id is null then raise exception 'NOT_FOUND'; end if; v_pin := _new_pin(_cfg(p_ev, 'pin_length')); v_salt := _new_token(); update teams set pin_salt = v_salt, pin_hash = _hash(v_salt || v_pin) where id = t.id; delete from pin_failures where event_id = p_ev and team_number = t.number; return jsonb_build_object('number', t.number, 'name', t.name, 'pin', v_pin); when 'trial_skip' then if a.paused then raise exception 'PAUSED'; end if; v_count := greatest(1, least(600, coalesce((p_args ->> 'seconds')::int, 30))); perform _shift_arena(a.id, -_secs(v_count)); perform _tick(a.id, true); return jsonb_build_object('skipped', v_count); when 'trial_reset' then perform _host_exec(p_ev, a.id, 'reset_arena', '{"confirm":"RESET"}'::jsonb, p_reason); update arenas set match_phase = 0, phase_started_at = null, phase_next_at = null, zone_hold = false where id = a.id; when 'trial_bots' then if a.phase <> 'lobby' then raise exception 'WRONG_PHASE'; end if; v_size := _cfg(p_ev, 'arena_size'); v_count := greatest(1, least(coalesce((p_args ->> 'count')::int, 3), v_size - (select count(*) from teams where arena_id = a.id)::int)); if v_count < 1 or (select count(*) from teams where arena_id = a.id) >= v_size then raise exception 'ALL_MAPS_FULL'; end if; for i in 1..v_count loop select coalesce(max(number), 0) + 1 into v_num from teams where event_id = p_ev; v_pin := _new_pin(6); v_salt := _new_token(); insert into teams(event_id, arena_id, number, name, pin_salt, pin_hash) values (p_ev, a.id, v_num, 'Bot-' || lpad(v_num::text, 2, '0'), v_salt, _hash(v_salt || v_pin)) returning * into t; perform _add_item(t.id, 'pistol', 1); perform _add_item(t.id, 'medkit', 1); v_tokens := '[]'::jsonb; for j in 1..4 loop v_tokens := v_tokens || to_jsonb((join_team(e.code, v_num, v_pin, v_names[1 + ((v_num * 4 + j) % 16)] || ' ' || j, true, true, null)) ->> 'token'); end loop; v_out := v_out || jsonb_build_object('team_id', t.id, 'number', v_num, 'tokens', v_tokens); end loop; return jsonb_build_object('bots', v_out); else raise exception 'UNKNOWN_COMMAND'; end case; return '{}'::jsonb; end $$;
